import{z as n,x as i,o as B,c as d,q as r,j as t,D as A,d as a,s as o,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"谄媚的度量","description":"","frontmatter":{"title":"谄媚的度量","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/aeval-sycophancy-metric.md","filePath":"llm/aeval-sycophancy-metric.md","lastUpdated":1791063341000}'),h={name:"llm/aeval-sycophancy-metric.md"};function D(p,E,m,c,C,F){const l=i("Mermaid");return B(),d("div",null,[E[2]||(E[2]=r('<h1 id="谄媚的度量" tabindex="-1">谄媚的度量 <a class="header-anchor" href="#谄媚的度量" aria-label="Permalink to &quot;谄媚的度量&quot;">​</a></h1><div class="epigraph"><p>用户先开口，答案就跟着走；谄媚的度量就是把「立场注入前后的答案差」收成一个比率，而不是靠一次不愉快的聊天体验。</p><footer>—— Sharma et al., 2023 分析 RLHF 模型的谄媚；Perez et al., 2022 的模型书写评测提供题面谱系</footer></div><p><a href="/llm/aeval-honesty-eval">上一课</a>把诚实拆成事实、校准、弃权三层协议。诚实轴的第一个对手不用幻觉登场：只要用户先表态，模型就可能改口，而用户被附和时体验反而更好——可用性测试永远测不出它。<a href="/llm/sycophancy">谄媚</a>写过先验与奖励来源；本课把度量钉成协议：键、盲判、配对基线、分轮记账。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>谄媚度量有四个缺口。一是键：用户断言与答案键冲突时，模型同意就是附和；没有键，附和与正确无从区分。二是基线：无立场注入时模型本来就会错的题，立场下出错不是谄媚是无能——不配对基线，两个失败混成一个数。三是裁判：裁判读完整对话再打分，用户立场同样激活裁判的附和先验，被测模型与测量仪器共享同一弱点。四是轮次：多轮里首次改口发生在第几轮，比最后一轮的答案携带更多失败史；只评末轮，用户已经读到的错误全部漏记。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="四种探针" tabindex="-1">四种探针 <a class="header-anchor" href="#四种探针" aria-label="Permalink to &quot;四种探针&quot;">​</a></h3><p><strong>前提注入</strong>：用户以声明或否定形式断言一个有答案键的命题，量附和率 \\(\\rho=\\Pr[\\text{输出与用户错误前提一致}]\\) 与纠正率。<strong>反馈压力</strong>：首答正确后用户追问「你确定吗」，量翻转率——首答对而被说服改错，是最贵的一种失败，要单独一列。<strong>价值翻转</strong>：无键的立场题（政治、品味），只报「随用户价值翻转」的描述统计，并交叉标记可验证事实是否跟着翻——价值尊重是合法的，事实跟着立场翻才是污染。<strong>分轮记账</strong>：记首次错误发生的轮次，不只评末轮。<span class="marginnote">「答案键」就是每道题预先存好的标准答案。有了它，「同意用户」才能分清两种情况：用户说得对而模型改口叫纠正，用户说错了模型还跟着叫附和——没有键，这两种行为在数据里长得一模一样。</span></p>',8)),(B(),t(s,null,{default:A(()=>[o(l,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20KEY%5B%22%E7%AD%94%E6%A1%88%E9%94%AE%E5%91%BD%E9%A2%98%E5%BA%93%22%5D%20--%3E%20INJ%5B%22%E7%AB%8B%E5%9C%BA%E6%B3%A8%E5%85%A5%EF%BC%9A%E5%A3%B0%E6%98%8E%E9%94%99%E8%AF%AF%E5%89%8D%E6%8F%90%22%5D%0A%20%20INJ%20--%3E%20GEN%5B%22%E6%A8%A1%E5%9E%8B%E5%9B%9E%E5%BA%94%22%5D%0A%20%20GEN%20--%3E%20JUDGE%5B%22%E7%9B%B2%E8%A3%81%E5%88%A4%EF%BC%9A%E4%B8%8D%E8%AF%BB%E7%94%A8%E6%88%B7%E7%AB%8B%E5%9C%BA%22%5D%0A%20%20JUDGE%20--%3E%20TRI%5B%22%E9%99%84%E5%92%8C%20%2F%20%E7%BA%A0%E6%AD%A3%20%2F%20%E5%9B%9E%E9%81%BF%20%E4%B8%89%E5%88%86%22%5D%0A%20%20TRI%20--%3E%20PAIR%5B%22%E9%85%8D%E5%AF%B9%E6%97%A0%E7%AB%8B%E5%9C%BA%E5%9F%BA%E7%BA%BF%22%5D%0A%20%20PAIR%20--%3E%20DIFF%5B%22%E5%B7%AE%E5%80%BC%E5%8D%B3%E8%B0%84%E5%AA%9A%E8%B4%A1%E7%8C%AE%22%5D%0A%20%20GEN%20--%3E%20TURN%5B%22%E5%88%86%E8%BD%AE%EF%BC%9A%E9%A6%96%E9%94%99%E8%BD%AE%E6%AC%A1%22%5D%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[a("配对基线是机制上的分账器：设无立场时正确率为 \\(a\\)，立场注入后正确率为 \\(a'\\)，附和率 \\(\\rho\\) 报的是行为差 \\(\\rho\\) 与 \\(a-a'\\) 要同表——只报 \\(\\rho\\) 的榜单会把弱模型的无能记成谄媚，只报 \\(a'\\) 的会反过来。"),e("span",{class:"marginnote"},"「配对」指同一道题测两遍：一遍不带立场、一遍带立场，两遍结果按题一一对应着比，而不是拿两份不同的题各算个平均分再相减。逐题配对才能看出哪些错误是立场「新增」出来的。"),a("三分判分里的回避率是第三个必要的格子：有的模型用拒答逃立场，既不附和也不纠正；不单列回避，纠正率被稀释，附和率被低估。")],-1)),(B(),t(s,null,{default:A(()=>[o(l,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20BASE%5B%22%E6%97%A0%E7%AB%8B%E5%9C%BA%E5%9F%BA%E7%BA%BF%EF%BC%9A%E5%90%8C%E4%B8%80%E6%89%B9%E9%A2%98%E5%85%88%E6%B5%8B%E4%B8%80%E9%81%8D%22%5D%20--%3E%20A_ERR%5B%22%E6%9C%AC%E6%9D%A5%E5%B0%B1%E4%BC%9A%E9%94%99%E7%9A%84%E9%A2%98%22%5D%0A%20%20STANCE%5B%22%E7%AB%8B%E5%9C%BA%E6%B3%A8%E5%85%A5%E5%90%8E%E5%86%8D%E6%B5%8B%E4%B8%80%E9%81%8D%22%5D%20--%3E%20S_ERR%5B%22%E7%AB%8B%E5%9C%BA%E4%B8%8B%E5%87%BA%E9%94%99%E7%9A%84%E9%A2%98%22%5D%0A%20%20S_ERR%20--%3E%20OVERLAP%5B%22%E4%B8%8E%E5%9F%BA%E7%BA%BF%E9%87%8D%E5%90%88%E7%9A%84%E9%94%99%E8%AF%AF%22%5D%0A%20%20S_ERR%20--%3E%20EXTRA%5B%22%E7%AB%8B%E5%9C%BA%E6%96%B0%E5%A2%9E%E7%9A%84%E9%94%99%E8%AF%AF%22%5D%0A%20%20OVERLAP%20--%3E%20INCOMP%5B%22%E8%AE%B0%E4%B8%BA%E6%97%A0%E8%83%BD%EF%BC%8C%E4%B8%8D%E7%AE%97%E8%B0%84%E5%AA%9A%22%5D%0A%20%20EXTRA%20--%3E%20SYC%5B%22%E8%AE%B0%E4%B8%BA%E8%B0%84%E5%AA%9A%E8%B4%A1%E7%8C%AE%22%5D%0A%20%20STANCE%20--%3E%20AVOID%5B%22%E6%8B%92%E7%AD%94%E4%B8%8D%E7%AB%99%E9%98%9F%22%5D%0A%20%20AVOID%20--%3E%20ESC%5B%22%E8%AE%B0%E4%B8%BA%E5%9B%9E%E9%81%BF%EF%BC%8C%E5%8D%95%E7%8B%AC%E4%B8%80%E5%88%97%22%5D%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=r('<p><span class="marginnote">初学者容易以为「拒答总比答错安全」，但在度量里回避必须单列：若 100 道题里模型拒答了 30 道，纠正率的分母就被抽走三成，剩下的纠正率看似升高，附和率却被稀释——两个指标同时失真，榜单没法比较。</span></p><p>盲判为什么有效：裁判的附和先验与生成模型走同一条通道——读到「我认定位……」之后再打分，量尺已偏。事实题把用户立场从裁判输入里剥掉、只对答案与键判，通道被切断；代价是裁判不再评「对话整体」，信息变少，这是诚实轴愿意付的钱（口径同<a href="/llm/sycophancy">谄媚</a>的比较器剥离）。<span class="marginnote">Sharma et al. 2023 的机制结论直接决定测量设计：人类偏好数据里附和常被标赢，RLHF 把偏好放大成策略——所以 SFT 后与 RLHF 后要各测一遍，差值才是偏好训练的谄媚贡献，混测会把预训练先验记到 RLHF 头上。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>产品需要共情与确认：复述需求、确认情绪不算谄媚，判分表里要给它们留合法格子，真值冲突时词典序——事实优先，口径与机制课一致。医疗、法律、金融域，纠正错误前提是安全要求，谄媚探针与安全对照集共用域分层。回避率升高可能是上一课越权拒绝的渗漏，两根轴的数字要对着看。最后，不用满意度当谄媚下降的证据：满意度衡量的恰是被附和的舒适。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>谄媚率必须配对无立场基线：分不清附和与无能的榜单没有意义。</li><li>盲判事实题：裁判不读用户立场，切断被测者与仪器的共同弱点。</li><li>三分记账：附和、纠正、回避；回避单列，防止两个率同时失真。</li><li>反馈压力下的翻转与首错轮次是独立列，末轮评分漏掉全部失败史。</li><li>价值题只报翻转的描述统计；事实跟着立场翻才是要修的污染。</li><li>出处：Sharma et al., 2023；Perez et al., 2022；Askell et al., 2021 的诚实轴口径。</li></ul>',6))])}const u=n(h,[["render",D]]);export{f as __pageData,u as default};
